            write_ptr += fsize;

            /* advance source pointer past the comma for the next field */
            if (comma != NULL) {
                p = comma + 1;
            } else {
                /* no more commas – remaining fields will be empty tokens */
                p = rec_str + strlen(rec_str); /* point to '\0' */
            }
        }
    }

    return 0;
}

